s0=200;mu=.10;sig=.30;T=1;x=np.linspace(80,420,600);scale=sig*np.sqrt(T);m=np.log(s0)+(mu-.5*sig**2)*T;pdf=stats.lognorm.pdf(x,s=scale,scale=np.exp(m));mean=s0*np.exp(mu*T);med=np.exp(m);ax.plot(x,pdf,color=ACCENT,lw=2);ax.axvline(med,color=GOOD,ls='--',label=f'median USD {med:.2f}');ax.axvline(mean,color=BAD,ls='--',label=f'mean USD {mean:.2f}');ax.set_xlabel('AAPL terminal price (USD/share)');ax.set_ylabel('Density');ax.set_title('A lognormal tail pulls the mean right',loc='left');ax.legend(fontsize=8)
